SELECT mp.subject_id, mp.hadm_id, (percentile_cont(0.75) within GROUP (ORDER BY pp.icd_code) - percentile_cont(0.25) within GROUP (ORDER BY pp.icd_code)) AS interquartile_range FROM male_patients mp JOIN procedures_icd pi ON mp.subject_id = pi.subject_id JOIN patient_procedures pp ON mp.subject_id = pp.subject_id AND mp.hadm_id = pp.hadm_id WHERE pi.order_provider_id IN (SELECT order_provider_id FROM male_surgeons) GROUP BY mp.subject_id, mp.hadm_id ORDER BY interquartile_range NULLS LAST;